'use server';

import { cookies } from 'next/headers';
import { revalidatePath } from 'next/cache';

const NOTIFICATION_COOKIE = 'notification-preference';

export async function toggleNotificationPreference() {
  const cookieStore = await cookies();
  const current = cookieStore.get(NOTIFICATION_COOKIE)?.value;
  const newValue = current === 'on' ? 'off' : 'on';

  cookieStore.set(NOTIFICATION_COOKIE, newValue, {
    path: '/',
    maxAge: 60 * 60 * 24 * 365, // 1 year
  });

  revalidatePath('/', 'layout');
}

