'use client';

import { toggleNotificationPreference } from './actions';

type NotificationToggleProps = {
  enabled: boolean;
};

export function NotificationToggle({ enabled }: NotificationToggleProps) {
  return (
    <form action={toggleNotificationPreference}>
      <label className="flex items-center gap-3 cursor-pointer">
        <span className="text-sm font-medium">Notifications</span>
        <button
          type="submit"
          className="relative inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
          style={{
            backgroundColor: enabled ? '#22c55e' : '#e5e7eb',
          }}
          aria-pressed={enabled}
          aria-label={`Notifications ${enabled ? 'on' : 'off'}. Click to toggle.`}
        >
          <span
            className="pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition"
            style={{
              transform: enabled ? 'translateX(1.25rem)' : 'translateX(0.125rem)',
            }}
          />
        </button>
        <span className="text-sm text-gray-600">{enabled ? 'On' : 'Off'}</span>
      </label>
    </form>
  );
}

