import { cookies } from 'next/headers';
import { NotificationToggle } from './notification-toggle';

const NOTIFICATION_COOKIE = 'notification-preference';

export default async function Home() {
  const cookieStore = await cookies();
  const notificationEnabled = cookieStore.get(NOTIFICATION_COOKIE)?.value === 'on';

  return (
    <main style={{ padding: '2rem', maxWidth: '600px', margin: '0 auto' }}>
      <h1 style={{ marginBottom: '1.5rem' }}>Settings</h1>
      <NotificationToggle enabled={notificationEnabled} />
    </main>
  );
}

